				if (field instanceof Initializer) continue; 
				char[][] typeName = field.type.getTypeName();
				if (typeName.length >= 1) // Add the first token, because only that can collide.
					usedNames.add(String.valueOf(typeName[0]));
			}
		}

		return usedNames;
	}

